import{_ as o,o as t,c as r,a5 as l}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"Vue Router 路由钩子函数概述","description":"Vue Router 提供了一些路由钩子函数，允许你在路由变化前后执行一些逻辑。这些钩子函数包括全局守卫、路由独享守卫、组件内守卫等。它们的执行顺序也有一定的规则。以下是对这些钩子函数的详细介绍和执行顺序说明。 全局守卫 1. 全局前置守卫 (beforeEach) 在每个路由改。","frontmatter":{"title":"Vue Router 路由钩子函数概述","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"Vue Router 提供了一些路由钩子函数，允许你在路由变化前后执行一些逻辑。这些钩子函数包括全局守卫、路由独享守卫、组件内守卫等。它们的执行顺序也有一定的规则。以下是对这些钩子函数的详细介绍和执行顺序说明。 全局守卫 1. 全局前置守卫 (beforeEach) 在每个路由改。","sidebarWeight":13,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/Vue Router 路由钩子函数概述.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/Vue Router 路由钩子函数概述.md","filePath":"posts/Vue系统教程/04-路由与状态管理/Vue Router 路由钩子函数概述.md"}'),n={name:"posts/Vue系统教程/04-路由与状态管理/Vue Router 路由钩子函数概述.md"};function u(a,e,s,i,f,g){return t(),r("div",null,[...e[0]||(e[0]=[l('<div><h1 id="vue-router-路由钩子函数概述" tabindex="-1">Vue Router 路由钩子函数概述 <a class="header-anchor" href="#vue-router-路由钩子函数概述" aria-label="Permalink to &quot;Vue Router 路由钩子函数概述&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue Router 路由钩子函数概述”的核心思路，并能把它用于实际开发或面试表达。 Vue Router 提供了一些路由钩子函数，允许你在路由变化前后执行一些逻辑。这些钩子函数包括全局守卫、路由独享守卫、组件内守卫等。它们的执行顺序也有一定的规则。以下是对这些钩子函数的详细介绍和执行顺序说明。</p></blockquote><p>全局守卫</p><ol><li><strong>全局前置守卫 (beforeEach)</strong></li></ol><ul><li>在每个路由改变前执行。</li><li>用于权限验证、重定向等。 router.beforeEach((to, from, next) =&gt; { // 做一些处理... next(); });</li></ul><ol start="2"><li><strong>全局解析守卫 (beforeResolve)</strong></li></ol><ul><li>在路由改变被确认前，且在所有组件内守卫和异步路由组件被解析之后执行。 router.beforeResolve((to, from, next) =&gt; { // 做一些处理... next(); });</li></ul><ol start="3"><li><strong>全局后置守卫 (afterEach)</strong></li></ol><ul><li>在每个路由改变后执行，不接受 next 参数。 router.afterEach((to, from) =&gt; { // 做一些处理... });</li></ul><h4 id="路由独享守卫" tabindex="-1">路由独享守卫 <a class="header-anchor" href="#路由独享守卫" aria-label="Permalink to &quot;路由独享守卫&quot;">​</a></h4><ol><li><strong>beforeEnter</strong></li></ol><ul><li>在路由配置中直接定义，只对某个特定路由有效。 const router = new VueRouter({ routes: [ { path: &#39;/some-path&#39;, component: SomeComponent, beforeEnter: (to, from, next) =&gt; { // 做一些处理... next(); } } ] });</li></ul><p>组件内守卫</p><ol><li><strong>beforeRouteEnter</strong></li></ol><ul><li>在路由进入该组件前调用。 export default { beforeRouteEnter(to, from, next) { // 做一些处理... next(); } };</li></ul><ol start="2"><li><strong>beforeRouteUpdate</strong></li></ol><ul><li>在当前路由改变时调用，适用于当前组件被复用的情况。 export default { beforeRouteUpdate(to, from, next) { // 做一些处理... next(); } };</li></ul><ol start="3"><li><strong>beforeRouteLeave</strong></li></ol><ul><li>在导航离开该组件的路由时调用。 export default { beforeRouteLeave(to, from, next) { // 做一些处理... next(); } };</li></ul><p>执行顺序</p><ol><li><strong>导航触发，先调用全局的 beforeEach 守卫</strong>。</li><li><strong>调用路由配置中 beforeEnter 守卫</strong>。</li><li><strong>解析异步路由组件</strong>。</li><li><strong>在失活的组件 (即将离开的组件) 内调用 beforeRouteLeave 守卫</strong>。</li><li><strong>调用组件内的 beforeRouteUpdate 守卫</strong>（如果存在）。</li><li><strong>在激活的组件 (即将进入的组件) 内调用 beforeRouteEnter 守卫</strong>。</li><li><strong>调用全局的 beforeResolve 守卫</strong>。</li><li><strong>导航被确认，调用全局的 afterEach 钩子</strong>。</li></ol><p>示例 const router = new VueRouter({ routes: [ { path: &#39;/home&#39;, component: Home, beforeEnter: (to, from, next) =&gt; { console.log(&#39;路由独享 beforeEnter&#39;); next(); } }, { path: &#39;/about&#39;, component: About } ] }); router.beforeEach((to, from, next) =&gt; { console.log(&#39;全局 beforeEach&#39;); next(); }); router.beforeResolve((to, from, next) =&gt; { console.log(&#39;全局 beforeResolve&#39;); next(); }); router.afterEach((to, from) =&gt; { console.log(&#39;全局 afterEach&#39;); }); new Vue({ router, render: h =&gt; h(App) }).$mount(&#39;#app&#39;);</p><p>总结 通过上面的介绍和示例，可以清楚地了解 Vue Router 中各类钩子函数的用途及其执行顺序。合理使用这些钩子函数，可以有效地控制路由行为，实现权限控制、数据预加载等功能。在实际项目中，结合具体需求选择合适的钩子函数进行处理，可以提高代码的可维护性和可读性。</p></div>',1)])])}const b=o(n,[["render",u]]);export{c as __pageData,b as default};
